    "questionText": "Birlisemuduruogretmenlerleyaptigitoplantidaogretim\nilkelerihakkindasunlari soylemistir.\n“Egerogrencilere agag sevgisini asilamak istiyorsak\nogrencininayaginintopragabasmasinisaglamamiz\ngerekiyor. Ogrenci, okul bahcesine kendisi agag\ndikecek,onukendisi sulayacak,gerektiginde kendisi\nilaglayacaktir.Agacidikerkenkuregitopragahangi\naciyla saplarsa dahaazenerji harcayacagini\ndusunurkenhemmatemafheMdefizikdersi\nbilgilerinden, agaci sularkenbiragacisulamaicin\ngerekli olansumiktarini dusunup su dongusunudegoz\nonundebulundururkenbiyoloji dersibilgilerinden,\nilaglamayaparkenilacinetkenmaddesinidusunup\ngerekli onlemleri almada kimya dersi bilgilerinden\nyararlanacaktir.\"\nBuna gore okul mudurunun vurguladigiogretim\nilkesiasagidakilerden hangisidir?",
